/** In lab order, grouped by category. */
export const ANIMATIONS: readonly CowAnimation[] = [
  breathe, blink, tailSwish, earFlick, lookAround, sniff, yawn, sleep, footTap, chew, munchGrass, gulp, burp, lickLips, nod, headShake, shrug, shockedJump, eyesPop, sweat, facepalm, sneeze, faint, sideEye, happyHop, dance, flex, spin, moonwalk, backflip, crownDrop, sunglassesDrop, cheer, peekUp, trotIn, trotOut, wave, waveBye, moo, abducted, fillWobble,
];

export const DEFAULT_ANIMATION_ID = 'breathe';

export function getAnimation(id?: string): CowAnimation {
  return ANIMATIONS.find((a) => a.id === id) ?? breathe;
}
